import json
H,W=17,29
g=[[1]*W for _ in range(H)]
for r in range(H):
    for c in range(W):
        if r==8 or c in (9,19): g[r][c]=3
p={(0,0):7,(0,1):9,(2,2):7,(3,5):0}
for br,rs in enumerate((range(0,8),range(9,17))):
  for bc,cs in enumerate((range(0,9),range(10,19),range(20,29))):
    for (r,c),v in p.items():
      rr=7-r if br%2 else r
      cc=8-c if bc%2 else c
      g[rs[rr]][cs[cc]]=v
print(json.dumps(g,separators=(',',':')))

